          "kind": "result",
          "claim_status": "observed",
          "source_origin": "research_note",
          "conditions": ["forward", "실행인자 있음", "eps=9.0e-05/1.0e-02/1.0e-01/1.0e+00 sweep"],
          "observations": ["total elapsed: 1360.22s", "F=40000 ratio=0.000 (모든 eps)", "results saved to results_cuda.csv"],
          "parameters": [],
          "measurements": [
