          "kind": "result",
          "claim_status": "observed",
          "source_origin": "research_note",
          "conditions": ["forward", "실행인자 있음", "eps=1.0e-02/1.0e-01/1.0e+00 (OCR 추출, 9.0e-03/9.0e-05 누락 가능)"],
